from collections import Counter
def f(g):
    H,W=len(g),len(g[0])
    cnt=Counter(v for r in g for v in r)
    rare=min(cnt,key=cnt.get)
    mark=set((i,j) for i in range(H) for j in range(W) if g[i][j]==rare)
    out=[r[:] for r in g]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=rare and any((i+di,j+dj) in mark for di in (-1,0,1) for dj in (-1,0,1) if 0<=i+di<H and 0<=j+dj<W):
                out[i][j]=1
    return out
